\label{Prop}\cite[Cor. 4.4]{Araki-1985-97} 
    For a representation $\pi$ of the form \eqref{matrix}, $\mathfrak{H}_j$ has no $G$-invariant complement in $\mathfrak{H}_{j+1}$ for each $j = 1, \cdots, n-1$ if and only if the following conditions hold
    \begin{enumerate}
        \item{
        \begin{align}
            c_{k, k+1} \notin B^1(\pi_{k+1}, \pi_k)\,, \quad\mbox{for}\quad k = 1, \cdots, n-1 \,.
        \end{align}}

        \item{
        \begin{align}
            \delta c_{kl} = -\sum_{j=k+1}^{l-1} c_{kj} \times c_{jl}\,, \quad\mbox{for}\quad 1 \leqslant k < l +1 \leqslant n+1 \,.
        \end{align}}        
    \end{enumerate}

\label{Theorem1}\cite[Thm. 2]{Araki-1985-97}
    Let $\pi^{}_1$ and $\pi_1^\sharp$ be a pair of adjoint-conjugate irreducible representations, and let $\pi_2$ be a representation admitting a $G$-invariant non-degenerate Hermitian form. Then, a Gupta-Bleuler triplet in the standard form exists if and only if there are non-zero classes $c^{}_{12}\in H^1(\pi^{}_2,\pi^{}_1)$ and $c_{12}^{\ast}\in H^1(\pi_1^\sharp,\pi^{}_2)$ such that
    \begin{align}
        c^{}_{12}\times c_{12}^\ast \,\in\, B_s^2(\pi_1^\sharp,\pi^{}_1) \,.
    \end{align}

\label{main thoerem}

Let $\pi\colon\; G = \mathrm{SO}_0(1,4)\longrightarrow\mathrm{GL}(V_{\mathrm{tot}})$ denote the representation associated with the indecomposable realization of the scalar discrete-series UIR $\Pi_{p,0}$, for a given $p=1,2,\cdots$. Then, $\pi$ admits a Gupta-Bleuler triplet in the standard form \eqref{standard}, together with a refined four-layer realization obtained by resolving its reducible intermediate sector into its two irreducible constituents. The corresponding three- and four-layer realizations are displayed below, respectively:
\begin{align}
    \pi(\texttt{g}) =
    \begin{pmatrix}
        \pi^{}_1 & c_{12} & c_{13} \\
            0 & \pi_2 & c_{23} \\
            0 & 0 & \pi_1^\sharp
    \end{pmatrix} \,, 
    \qquad\;\overset{\scalebox{2.6}[2.3]{$\curvearrowright$}}{\qquad^{}} \qquad \pi=\;\vcenter{\hbox{ 
\begin{tikzpicture}[baseline=(m.center)]
  \matrix (m) [
    matrix of math nodes, 
    left delimiter={(}, 
    right delimiter={)}, 
    nodes in empty cells,
    nodes={inner sep=3pt, anchor=center},
    ampersand replacement=\&,
    column 1/.style={nodes={minimum width=1.0cm}},
    column 2/.style={nodes={minimum width=1.0cm}},
    column 3/.style={nodes={minimum width=2.0cm}},
    column 4/.style={nodes={minimum width=1.4cm}}
  ] {
    \pi^{}_1\& c_{1{2^\prime}} \& c_{1{\overline{2}^\prime}} \& c_{13} \\
    0 \& \pi^{}_{2^\prime} \& c_{{2^\prime}{{\overline{2}^\prime}}}=0 \& c_{{2^\prime}3} \\
    0 \& 0 \& \pi_{{\overline{2}^\prime}} \& c_{{\overline{2}^\prime} 3} \\
    0 \& 0 \& 0 \& \pi_1^\sharp  \\
  };
  \draw[dashed, gray] (m-1-1.north east) -- (m-4-1.south east);
  \draw[dashed, gray] (m-1-3.north east) -- (m-4-3.south east);
  \draw[dashed, gray] (m-1-1.south west) -- (m-1-4.south east);
  \draw[dashed, gray] (m-3-1.south west) -- (m-3-4.south east);
\end{tikzpicture}
}}\,,
\end{align}
\begin{align}
\pi = \pi_1^\sharp \longrightarrow \pi_2 \longrightarrow \pi^{}_1\,,
\qquad\;\overset{\scalebox{2.6}[2.3]{$\curvearrowright$}}{\qquad^{}} \qquad
\pi = \vcenter{\hbox{ 
  \xymatrix@C=1.5em@R=1em{
    & \pi^{}_{2^\prime} \ar[dr] & \\
    \pi_1^\sharp \ar[ur] \ar[dr] & & \pi^{}_1\\
    & \pi_{{\overline{2}^\prime}} \ar[ur] &
  } 
}}\,, \hspace{3.1cm}
\end{align}
such that,
\begin{align} \label{yields}
    0 \neq  c_{12} \in H^1(\pi^{}_2, \pi^{}_1) \,, \qquad\;\overset{\scalebox{2.6}[2.3]{$\curvearrowright$}}{\qquad^{}}\qquad 
    \begin{cases}
        0 \neq c_{12^\prime}\in H^1(\pi^{}_{2^\prime},\pi^{}_1) \,, \\[5pt]
        0 \neq c_{1{{\overline{2}^\prime}}}\in H^1(\pi_{{\overline{2}^\prime}},\pi^{}_1) \,,
    \end{cases} 
\end{align}
\begin{align}
    0 \neq  c_{12}^\ast \in H^1(\pi_1^\sharp,\pi^{}_2) \,, \qquad\;\overset{\scalebox{2.6}[2.3]{$\curvearrowright$}}{\qquad^{}}\qquad
    \begin{cases}
        0 \neq c^\ast_{12^\prime} \in H^1(\pi^{\sharp}_1, \pi^{}_{2^\prime}) \,, \\[5pt]
        0 \neq c^\ast_{1{{\overline{2}^\prime}}} \in H^1(\pi^{\sharp}_1, \pi_{{\overline{2}^\prime}}) \,,
    \end{cases} 
\end{align}
\begin{align}
    c^{}_{12} \times c_{12}^\ast \in B_s^2(\pi_1^\sharp, \pi^{}_1) \,, \qquad\;\overset{\scalebox{2.6}[2.3]{$\curvearrowright$}}{\qquad^{}}\qquad c^{}_{12^\prime_{}}\times c_{12^\prime_{}}^{\ast} + c^{}_{1{\overline{2}^\prime}}\times c_{1{\overline{2}^\prime}}^{\ast} \in B_s^2(\pi_1^\sharp ,\, \pi^{}_1) \,.
\end{align}
Here, $\pi^{}_{2^\prime}$ and $\pi_{{\overline{2}^\prime}}$ denote two equivalent realizations of the UIR $\Pi_{p,0}$, carried by $V^\prime$ and $\overline{V^\prime}$, respectively. By contrast, $\pi^{}_1$ and $\pi_1^\sharp$ denote mutually adjoint-conjugate finite-dimensional representations, carried by $V_g$ and $V_s$, respectively, each Weyl equivalent to $\Pi_{p,0}$, in the sense of possessing the same eigenvalues of the dS Casimir operators as $\Pi_{p,0}$.

\textbf{Step I.} Let $P_1$, $P_2 \overset{\scalebox{1.6}[1.3]{$\curvearrowright$}}{\big(=}P_{2^\prime} + P_{{\overline{2}^\prime}})$, and $P_3$ denote the projections associated with the decomposition \eqref{Araki-direct-sum-bulk333}. Explicitly (see Table \ref{Table 1}),
\begin{align}
    P_1 &\colon\; V_{\mathrm{tot}} \; \longrightarrow\; V_g \,, \qquad P_1 \Phi = \sum_{L=0}^{p-1} \left\langle \Phi \,,\, \phi^{(s)}_L \right\rangle_{\vphantom{}_{\mathrm{KG}}} \;\phi^{(g)}_L \,, \\[3pt]
    P_2 \overset{\scalebox{1.6}[1.3]{$\curvearrowright$}}{\big(=}P_{2^\prime} + P_{{\overline{2}^\prime}}) &\colon\; V_{\mathrm{tot}} \; \longrightarrow\; V^\prime\oplus \overline{V^\prime} \,, \qquad P_2 \Phi = \underbrace{\sum_{L=p}^\infty \left\langle \Phi \,,\, \phi^{}_L \right\rangle_{\vphantom{}_{\mathrm{KG}}} \;\phi^{}_L}_{P^{}_{2^\prime} \colon\; V_{\mathrm{tot}} \; \longrightarrow\; V^\prime} \;+\;\, \underbrace{\sum_{L=p}^\infty \left\langle \Phi \,,\, -\overline{\phi^{}_L} \right\rangle_{\vphantom{}_{\mathrm{KG}}} \;\overline{\phi^{}_L}}_{P_{{\overline{2}^\prime}} \colon\; V_{\mathrm{tot}} \; \longrightarrow\; \overline{V^\prime}} \,, \\[5pt] 
    P_3 &\colon\; V_{\mathrm{tot}} \; \longrightarrow\; V_s \,, \qquad P_3 \Phi = \sum_{L=0}^{p-1} \left\langle \Phi \,,\, \phi^{(g)}_L \right\rangle_{\vphantom{}_{\mathrm{KG}}} \;\phi^{(s)}_L \,.
\end{align}
We recall that $\{\phi^{(g)}_{L<p}\}$ and $\{\phi^{(s)}_{L<p}\}$ are KG-paired bases of $V_g$ and $V_s$, respectively, while $\{\phi_{L\geqslant p}\}$ and $\{\overline{\phi_{L\geqslant p}}\}$ are KG-``orthonormal'' bases of $V^\prime$ and $\overline{V^\prime}$, respectively; see Table \ref{Table 1}. We note that every vector $\Phi\in V_{\mathrm{tot}}$ admits the unique decomposition
\begin{align}\label{p1+p2+p3}
    \Phi &=\quad P_1 \Phi \quad+\quad P_2 \Phi \;\overset{\scalebox{1.6}[1.3]{$\curvearrowright$}}{\Big(=} \; P_{2^\prime}\Phi + P_{{\overline{2}^\prime}} \Phi\Big)  \quad+\quad P_3 \Phi \,.
\end{align}
Moreover, the maps $P_i$, $i=1,2 \overset{\scalebox{1.6}[1.3]{$\curvearrowright$}}{\big(=}2^\prime,{\overline{2}^\prime}\big), 3$, satisfy
\begin{align}
    P_iP_j=\delta_{ij}P_i \,,
\end{align}
where $\delta_{ij}$ denotes the Kronecker delta.

\textbf{Step II.} Following Araki's notation, let $\pi \colon\; G = \mathrm{SO}_0(1,4) \longrightarrow \mathrm{GL}(V_{\mathrm{tot}})$ denote the representation associated with the indecomposable scalar discrete-series realization $\Pi_{p,0}$, $p=1,2,\cdots$. With respect to the decomposition \eqref{p1+p2+p3} and the corresponding dS-invariant subspace structure summarized in Table \ref{Table 1}, we obtain
\begin{align}
    \label{la-1} \pi(\texttt{g})P_1 &\;=\quad \underbrace{P_1 \pi(\texttt{g})P_1}_{=:\, \pi^{}_1(\texttt{g})} \quad+\quad \underbrace{ P_2 \pi(\texttt{g})P_1}_{=:\, c_{21}(\texttt{g}) \,=\, 0} \;\overset{\scalebox{1.6}[1.3]{$\curvearrowright$}}{\Bigg(=}\;\underbrace{ P_{2^\prime}\pi(\texttt{g})P_1}_{=:\, c_{2^\prime 1}(\texttt{g})\,=\,0} \;+\; \underbrace{ P_{{\overline{2}^\prime}} \pi(\texttt{g})P_1}_{=:\, c_{{\overline{2}^\prime} 1}(\texttt{g})\,=\,0}\Bigg) \quad+\quad \underbrace{P_3 \pi(\texttt{g})P_1}_{=:\, c_{31}(\texttt{g}) \,=\, 0} \nonumber\\[3pt]
    &\;=\quad \pi^{}_1(\texttt{g}) \,,
\end{align}
\begin{align}   
    \label{la-2} \pi(\texttt{g})P_2 \;\overset{\scalebox{1.6}[1.3]{$\curvearrowright$}}{\Bigg(=} 
    \begin{array}{cc}
        &\pi(\texttt{g}) P_{2^\prime} \\[3pt]
        +\!\!\!\!\!\!& \\[3pt]
        &\pi(\texttt{g}) P_{{\overline{2}^\prime}}     
    \end{array}
    \Bigg) 
    &\;=\quad \underbrace{P_1 \pi(\texttt{g})P_2}_{=:\, c_{12}(\texttt{g})} \;\overset{\scalebox{1.6}[1.3]{$\curvearrowright$}}{\Bigg(=}
    \begin{array}{cc}
        &\underbrace{P_1\pi(\texttt{g})P_{2^\prime}}_{=:\, c_{12^\prime}(\texttt{g})} \\[3pt]
        +\!\!\!\!\!\!& \\[3pt]
        &\underbrace{P_1\pi(\texttt{g})P_{{\overline{2}^\prime}}}_{=:\, c_{1{\overline{2}^\prime}}(\texttt{g})}
    \end{array}
    \Bigg) \quad+\quad \underbrace{P_2 \pi(\texttt{g})P_2}_{=:\, \pi^{}_2(\texttt{g})} \;\overset{\scalebox{1.6}[1.3]{$\curvearrowright$}}{\Bigg(=}
    \begin{array}{cc}
        &\underbrace{P_{2^\prime}\pi(\texttt{g})P_{2^\prime}}_{=:\, \pi^{}_{2^\prime}(\texttt{g})} \;+\; \underbrace{ P_{{\overline{2}^\prime}}\pi(\texttt{g})P_{2^\prime}}_{=:\, c_{{\overline{2}^\prime} 2^\prime}(\texttt{g}) \,=\, 0} \\[3pt]
        +\!\!\!\!\!\!& \\[3pt]
        &\underbrace{ P_{2^\prime}\pi(\texttt{g})P_{{\overline{2}^\prime}}}_{=:\, c_{2^\prime{\overline{2}^\prime}}(\texttt{g}) \,=\, 0} \;+\; \underbrace{ P_{{\overline{2}^\prime}}\pi(\texttt{g})P_{{\overline{2}^\prime}}}_{=:\, \pi_{{\overline{2}^\prime}}(\texttt{g})}
    \end{array} 
    \Bigg)\nonumber\\[8pt] 
    & \qquad + \underbrace{P_3 \pi(\texttt{g})P_2}_{=:\, c_{32}(\texttt{g}) \,=\, 0} \;\overset{\scalebox{1.6}[1.3]{$\curvearrowright$}}{\Bigg(=}
    \begin{array}{cc}
        &\underbrace{ P_3\pi(\texttt{g})P_{2^\prime}}_{=:\, c_{32^\prime}(\texttt{g}) \,=\,0} \\[3pt]
        +\!\!\!\!\!\!& \\[3pt]
        &\underbrace{ P_3\pi(\texttt{g})P_{{\overline{2}^\prime}}}_{=:\, c_{3{\overline{2}^\prime}}(\texttt{g})\,=\,0}
    \end{array}
    \Bigg) \nonumber\\[8pt]
    &=\quad c_{12}(\texttt{g}) \;\overset{\scalebox{1.6}[1.3]{$\curvearrowright$}}{\Big(=} 
    \begin{array}{cc}
        &c_{12^\prime}(\texttt{g}) \\[3pt]
        +\!\!\!\!\!\!& \\[3pt]
        &c_{1{\overline{2}^\prime}}(\texttt{g})
    \end{array}
    \Big) \quad+\quad \pi^{}_2(\texttt{g}) \;\overset{\scalebox{1.6}[1.3]{$\curvearrowright$}}{\Big(=}
    \begin{array}{cc}
        &\pi^{}_{2^\prime}(\texttt{g}) \\
        +\!\!\!\!\!\!& \\[3pt]
        &\pi_{{\overline{2}^\prime}}(\texttt{g})
    \end{array} \Big)\,, 
\end{align}
or, more precisely, $\pi(\texttt{g}) P_{2^\prime} = c_{12^\prime}(\texttt{g}) +  \pi^{}_{2^\prime}(\texttt{g})$ and $\pi(\texttt{g}) P_{{\overline{2}^\prime}} = c_{1{\overline{2}^\prime}}(\texttt{g}) +  \pi_{{\overline{2}^\prime}}(\texttt{g})$, and
\begin{align}    
    \label{la-3} \pi(\texttt{g})P_3 &\;=\quad \underbrace{P_1 \pi(\texttt{g})P_3}_{=:\,c_{13}(\texttt{g})} \quad+\quad \underbrace{P_2 \pi(\texttt{g})P_3}_{=:\,c_{23}(\texttt{g})} \;\overset{\scalebox{1.6}[1.3]{$\curvearrowright$}}{\Bigg(=}\;\underbrace{ P_{2^\prime}\pi(\texttt{g})P_3}_{=:\, c_{2^\prime 3}(\texttt{g})} \;+\; \underbrace{ P_{{\overline{2}^\prime}} \pi(\texttt{g})P_3}_{=:\, c_{{\overline{2}^\prime} 3}(\texttt{g})}\Bigg) \quad+\quad \underbrace{P_3 \pi(\texttt{g})P_3}_{=:\,\pi^{}_3(\texttt{g})} \nonumber\\[3pt]
    &\;=\quad c_{13}(\texttt{g}) \quad+\quad c_{23}(\texttt{g}) \;\overset{\scalebox{1.6}[1.3]{$\curvearrowright$}}{\Big(=} c_{2^\prime 3}(\texttt{g}) + c_{{\overline{2}^\prime} 3}(\texttt{g})\Big) \quad+\quad \pi^{}_3(\texttt{g}) \,.
\end{align}
Then, the action of the dS representation $\pi\colon\; G=\mathrm{SO}_0(1,4) \longrightarrow \mathrm{GL}(V_{\mathrm{tot}})$ takes the form\footnote{Note that, by construction, we have 
\begin{align*}
    \pi^{}_1(\texttt{g}) \Phi = \pi^{}_1(\texttt{g}) \phi^{(g)} \,, \quad \pi^{}_2(\texttt{g}) \Phi = \pi^{}_2(\texttt{g}) \phi^{(2)}\,, \quad \pi^{}_3(\texttt{g}) \Phi = \pi^{}_3(\texttt{g}) \phi^{(s)}\,, \quad c_{12}(\texttt{g}) \Phi = c_{12}(\texttt{g}) \phi^{(2)} \,, \quad c_{23}(\texttt{g}) \Phi = c_{23}(\texttt{g}) \phi^{(s)} \,,
\end{align*}
\begin{align*}
    \pi^{}_{2^\prime}(\texttt{g}) \Phi = \pi^{}_{2^\prime}(\texttt{g}) \phi \,, \quad \pi_{{\overline{2}^\prime}}(\texttt{g}) \Phi = \pi_{{\overline{2}^\prime}}(\texttt{g}) \overline{\phi}\,, \quad c_{12^\prime}(\texttt{g}) \Phi = c_{12^\prime}(\texttt{g}) \phi \,, \quad c_{1{\overline{2}^\prime}}(\texttt{g}) \Phi = c_{1{\overline{2}^\prime}}(\texttt{g}) \overline{\phi}\,, \quad c_{2^\prime 3}(\texttt{g}) \Phi = c_{2^\prime 3}(\texttt{g}) \phi^{(s)} \,, \quad c_{{\overline{2}^\prime} 3}(\texttt{g}) \Phi = c_{{\overline{2}^\prime} 3}(\texttt{g}) \phi^{(s)} \,. 
\end{align*}}
\begin{align}\label{27}
    \pi(\texttt{g})\,\Phi &=\quad \pi(\texttt{g}) P_1 \,\Phi \quad+\quad \pi(\texttt{g}) P_2 \,\Phi \;\overset{\scalebox{1.6}[1.3]{$\curvearrowright$}}{\Big(=} \pi(\texttt{g}) P_{2^\prime}\,\Phi + \pi(\texttt{g}) P_{{\overline{2}^\prime}}\,\Phi \Big) \quad+\quad \pi(\texttt{g}) P_3 \,\Phi \nonumber\\[3pt]
    &=:\quad \pi^{}_1(\texttt{g}) \,\phi^{(g)} \nonumber\\
    &\quad +\quad c_{12}(\texttt{g})\phi^{(2)} \;\overset{\scalebox{1.6}[1.3]{$\curvearrowright$}}{\Big(=} c_{12^\prime}(\texttt{g})\phi + c_{1{\overline{2}^\prime}}(\texttt{g})\overline{\phi} \Big) \quad+\quad \pi^{}_2(\texttt{g})\phi^{(2)} \;\overset{\scalebox{1.6}[1.3]{$\curvearrowright$}}{\Big(=} \pi^{}_{2^\prime}(\texttt{g})\phi + \pi_{{\overline{2}^\prime}}(\texttt{g})\overline{\phi} \Big) \nonumber\\
    &\quad+\quad c_{13}(\texttt{g})\phi^{(s)} \quad+\quad c_{23}(\texttt{g})\phi^{(s)} \;\overset{\scalebox{1.6}[1.3]{$\curvearrowright$}}{\Big(=} c_{2^\prime 3}(\texttt{g})\phi^{(s)} + c_{{\overline{2}^\prime} 3}(\texttt{g})\phi^{(s)} \Big) \quad+\quad \pi^{}_3(\texttt{g}) \phi^{(s)} \,.
\end{align}

\textbf{Step III.} We observe the following:
\begin{enumerate}
    \item{The representation $\pi$ of $G=\mathrm{SO}_0(1,4)$ on $V_{\mathrm{tot}}$ is \emph{reducible} (see footnote \ref{footnote indecom}), since both the standard three-layer filtration and its refined four-layer counterpart contain non-trivial proper closed $G$-invariant subspaces. This invariant subspace structure is summarized in Table \ref{Table 1}.}

    \item{The representation $\pi$ of $G=\mathrm{SO}_0(1,4)$ on $V_{\mathrm{tot}}$ is topologically \emph{indecomposable} (see footnote \ref{footnote indecom}), since there exist no non-trivial closed $G$-invariant subspaces ${\mathfrak{E}}_1$ and ${\mathfrak{E}}_2$ satisfying ${\mathfrak{E}}_1\cap{\mathfrak{E}}_2=\{0\}$ and $(({\mathfrak{E}}_1 + {\mathfrak{E}}_2)^\perp)^\perp=V_{\mathrm{tot}}$ (see Table \ref{Table 1}). This indecomposability is reflected in the non-vanishing extension maps $c_{12} \overset{\scalebox{1.6}[1.3]{$\curvearrowright$}}{(=} c_{12^\prime} + c_{1{\overline{2}^\prime}})$ and $c_{23} \overset{\scalebox{1.6}[1.3]{$\curvearrowright$}}{(=} c_{2^\prime 3} + c_{{\overline{2}^\prime} 3})$, whose presence couples the successive layers of the Araki filtration and prevents the representation from splitting into a direct sum of invariant subrepresentations.}

    \item{The middle representation $\pi_2$ is reducible and topologically decomposable, admitting the direct-sum decomposition into the irreducible representations $\pi^{}_{2^\prime}$ and $\pi_{{\overline{2}^\prime}}$ carried by $V^\prime$ and $\overline{V^\prime}$, respectively. Equivalently, $V^\prime \cap \overline{V^\prime} = \{0\}$ and $\left( \left(V^\prime + \overline{V^\prime} \right)^{\perp_{\vphantom{}_{\mathrm{KG}}}} \right)^{\perp_{\vphantom{}_{\mathrm{KG}}}} = V^\prime + \overline{V^\prime}$ (see Table \ref{Table 1} and footnote \ref{footnote indecom}).}

    \item{The induced representations $\pi^{}_1$ on $V_g$ and $\pi^{}_3$ on $V_s$ are irreducible and, consequently, topologically indecomposable.}

    \item{The induced representations $\pi_1$ and $\pi_3$ are mutually adjoint-conjugate,
    \begin{align}\label{3sharp=1}
        \pi^{}_3 \simeq \pi_1^\sharp \,, \quad \pi_3^\sharp \simeq \pi^{}_1 \,,
    \end{align}
    as follows:
    \begin{enumerate}
        \item{From ${V_g}^{\perp_{\vphantom{}_{\mathrm{KG}}}} = V^\prime \oplus \overline{V^\prime} \oplus V_g$ and ${V_s}^{\perp_{\vphantom{}_{\mathrm{KG}}}} = V^\prime \oplus \overline{V^\prime} \oplus V_s$ (see Table \ref{Table 1}), together with the non-degenerate KG pairing between $V_g$ and $V_s$ in Eq. \eqref{gs}, the two sectors are mutually adjoint-conjugate,
        \begin{align}\label{gssharp}
            V_g^\sharp \simeq V_s \,, \quad V_s^\sharp \simeq V_g \,.
        \end{align}}

        \item{Using Eqs. \eqref{la-1} and \eqref{la-3}, the KG-orthogonality relations summarized in Table \ref{Table 1}, and the $G$-invariance of the KG form, we obtain
        \begin{align} \label{suprise}
            \left\langle \pi_3(\texttt{g})\phi^{(s)} \,,\, \pi_1(\texttt{g})\phi^{(g)} \right\rangle_{\vphantom{}_{\mathrm{KG}}} =&\, \left\langle \pi(\texttt{g})\phi^{(s)} \,,\, \pi(\texttt{g})\phi^{(g)} \right\rangle_{\vphantom{}_{\mathrm{KG}}} \nonumber\\[5pt]
            &\, -\; \underbrace{\left\langle c_{23}(\texttt{g})\phi^{(s)} \,,\, \pi(\texttt{g})\phi^{(g)} \right\rangle_{\vphantom{}_{\mathrm{KG}}}}_{=\,0} -\; \underbrace{\left\langle c_{13}(\texttt{g})\phi^{(s)} \,,\, \pi(\texttt{g})\phi^{(g)} \right\rangle_{\vphantom{}_{\mathrm{KG}}}}_{=\,0} \nonumber\\
            =&\, \left\langle \phi^{(s)} \,,\, \phi^{(g)} \right\rangle_{\vphantom{}_{\mathrm{KG}}} \,.
        \end{align}
        Hence, by the definition \eqref{conj-def} and Eq. \eqref{gssharp}, $\pi^{}_3 \simeq \pi_1^\sharp$ and, equivalently, $\pi_3^\sharp \simeq \pi^{}_1$.}
    \end{enumerate}}

    \item{By the same argument as in Eq. \eqref{suprise}, applied to the non-degenerate restriction of the KG form to $V^\prime \oplus \overline{V^\prime}$ and to each of its two components, one likewise obtains
    \begin{align} \label{sharps}
        \pi^{}_2 \simeq \pi_2^\sharp \,, \quad \pi^{}_{2^\prime} \simeq \pi^\sharp_{2^\prime} \,, \quad \pi_{{\overline{2}^\prime}} \simeq \pi^\sharp_{{\overline{2}^\prime}} \,.
    \end{align}}

    \item{The cochain $c_{23}$ is the adjoint of $c_{12}$ in the sense of Eq. \eqref{eq:3.1},
    \begin{align}\label{akse0}
        c^{}_{23} = c_{12}^{\ast} \,.
    \end{align}
    Indeed, using Eqs. \eqref{la-3} and \eqref{la-2}, the KG-orthogonality relations summarized in Table \ref{Table 1}, and the $\mathrm{SO}_0(1,4)$-invariance of the KG form, we obtain 
    \begin{align}\label{Alan-1}
        \left\langle c_{23}(\texttt{g}^{-1})\phi^{(s)} \;,\; \phi_2 \right\rangle_{\vphantom{}_\mathrm{KG}} &= \left\langle \pi(\texttt{g}^{-1})\phi^{(s)} \;,\; \phi_2 \right\rangle_{\vphantom{}_\mathrm{KG}} - \;\;\underbrace{\left\langle \pi^{}_3(\texttt{g}^{-1})\phi^{(s)} \;,\; \phi_2 \right\rangle_{\vphantom{}_\mathrm{KG}}}_{=\, 0} - \;\;\underbrace{\left\langle c^{}_{13}(\texttt{g}^{-1})\phi^{(s)} \;,\; \phi_2 \right\rangle_{\vphantom{}_\mathrm{KG}}}_{=\, 0} \nonumber\\
        &= \left\langle \phi^{(s)} \;,\; \pi(\texttt{g})\phi_2 \right\rangle_{\vphantom{}_\mathrm{KG}} \nonumber\\
        &= \underbrace{\left\langle \phi^{(s)} \;,\; \pi^{}_2(\texttt{g})\phi_2 \right\rangle_{\vphantom{}_\mathrm{KG}}}_{=\, 0} + \;\;\left\langle \phi^{(s)} \;,\; c_{12}(\texttt{g})\phi_2 \right\rangle_{\vphantom{}_\mathrm{KG}} = \left\langle \phi^{(s)} \;,\; c_{12}(\texttt{g})\phi_2 \right\rangle_{\vphantom{}_\mathrm{KG}} \,.
    \end{align}
    An analogous argument yields
    \begin{align}\label{akse}
        c^{}_{2^\prime 3} = c_{12^\prime}^\ast\,, \quad\mbox{and}\quad c^{}_{{\overline{2}^\prime}3} = c_{1{\overline{2}^\prime}}^\ast \,.
    \end{align}}
\end{enumerate}

\textbf{Step IV.} The action \eqref{27} admits the following upper-triangular matrix realization (left), analogous to the standard form \eqref{standard}. Decomposing the middle sector into its two irreducible components further refines this three-layer structure into the corresponding four-layer form shown on the right,
\begin{align}\label{Araki-matrix-bulk}
    \pi(\texttt{g})\Phi =
    \begin{pmatrix}
        \pi^{}_1(\texttt{g}) & c^{}_{12}(\texttt{g}) & c^{}_{13} (\texttt{g}) \\
        0 & \pi^{}_2(\texttt{g}) & c^{}_{23}(\texttt{g}) \\
        0 & 0 & \pi^{}_3(\texttt{g})
    \end{pmatrix}
    \!\!\begin{pmatrix}
        \phi^{(g)}\\
        \phi^{(2)} \\
        \phi^{(s)}
    \end{pmatrix} \,,
    \quad\;\overset{\scalebox{1.6}[1.3]{$\curvearrowright$}}{\qquad^{}}\quad 
    \pi(\texttt{g})\Phi = \begin{pmatrix}
        \pi^{}_1(\texttt{g}) & c^{}_{1{2^\prime}}(\texttt{g}) & c_{1{{\overline{2}^\prime}}}(\texttt{g}) & c^{}_{13}(\texttt{g}) \\[3pt]
        0 & \pi^{}_{2^\prime}(\texttt{g}) & c^{}_{{2^\prime}{{\overline{2}^\prime}}}(\texttt{g})=0 & c^{}_{{2^\prime}3}(\texttt{g}) \\[3pt]
        0 & 0 & \pi_{{\overline{2}^\prime}}(\texttt{g}) & c^{}_{{{\overline{2}^\prime}}3}(\texttt{g}) \\[3pt]
        0 & 0 & 0 & \pi^{}_3(\texttt{g})
    \end{pmatrix}
    \!\!\begin{pmatrix}
        \phi^{(g)}\\
        \phi \\
        \overline{\phi} \\
        \phi^{(s)}
    \end{pmatrix}\,.
\end{align}

