Note that a non-trivial class $c_{ij} \in H^1(\pi_j,\pi_i) = Z^1(\pi_j,\pi_i)/B^1(\pi_j,\pi_i)$ is represented by a $1$-cocycle $c_{ij} \in Z^1(\pi_j,\pi_i)$, with $(\delta c_{ij})(\texttt{g}_1,\texttt{g}_2) = 0$, such that $c_{ij} \notin B^1(\pi_j,\pi_i)$, i.e., there exists no fixed $b_{ij} \in C^0(\pi_j,\pi_i)$ satisfying 
\begin{align}
    c_{ij}(\texttt{g}_1) = (\delta b_{ij})(\texttt{g}_1) = \pi_i(\texttt{g}_1)b_{ij} - b_{ij}\pi_j(\texttt{g}_1) \,,
\end{align}
for all $\texttt{g}_1, \texttt{g}_2 \in G = \mathrm{SO}_0(1,4)$. For each of the $1$-cocycles listed above, including $c_{12}$ and $c_{12^\prime}$, the condition $(\delta c_{ij})(\texttt{g}_1, \texttt{g}_2) = 0$ has already been established explicitly; hence $c_{ij}\in Z^1(\pi_j, \pi_i)$. It therefore remains only to show that $c_{ij}\notin B^1(\pi_j,\pi_i)$ in order to conclude that $c_{ij}$ defines a non-trivial class in $H^1(\pi_j,\pi_i)$. Explicitly,
\begin{enumerate}
    \item{$c_{12}\notin B^1(\pi^{}_2,\pi^{}_1)$. If $c_{12}$ were a $1$-coboundary, then, by definition, there would exist a fixed linear map $b_{12} \; \left(\in C^0(\pi^{}_2,\pi^{}_1)\right) \colon\; V^\prime\oplus\overline{V^\prime}\longrightarrow V_g$, such that, for every $\texttt{g}_1 \in G=\mathrm{SO}_0(1,4)$,
    \begin{align}\label{c12} 
        c_{12}(\texttt{g}_1) = (\delta b_{12})(\texttt{g}_1) = \pi^{}_1(\texttt{g}_1)b_{12} - b_{12}\pi^{}_2(\texttt{g}_1) \,.
    \end{align}
    On the other hand, for each $\phi^{(2)} \in V^\prime \oplus \overline{V^\prime}$, Eq. \eqref{la-2} gives
    \begin{align} \label{la-2'}
        \pi(\texttt{g}_1)\phi^{(2)} = \underbrace{\pi^{}_2(\texttt{g}_1) \phi^{(2)}}_{\in\,V^\prime\oplus\overline{V^\prime}} + \,\underbrace{c_{12}(\texttt{g}_1) \phi^{(2)}}_{\in\,V_g} \,.
    \end{align}
    Substituting Eq. \eqref{c12} into \eqref{la-2'}, and using the fact that $\pi(\texttt{g}_1) b_{12} = \pi^{}_1(\texttt{g}_1) b_{12}$ (which follows from $b_{12}\phi^{(2)} \in V_g$ and the $G= \mathrm{SO}_0(1,4)$-invariance of $V_g$), we obtain
    \begin{align} \label{61}
        \pi(\texttt{g}_1)(1 - b_{12}) \phi^{(2)} = (1 - b_{12}) \pi^{}_2(\texttt{g}_1) \phi^{(2)} \,.
    \end{align}
    Notably, the vectors $w := (1-b_{12})\phi^{(2)}$ span a subspace $W \subset \mathfrak{H}_2 = V_g \oplus V^\prime \oplus \overline{V^\prime}$ (see Eq. \eqref{32}). One has $W \cap V_g = \{0\}$: indeed, if $w \in V_g$, then $P_2w = \phi^{(2)} = 0$, and hence $w=0$. Moreover, every $v_g+\phi^{(2)}\in\mathfrak{H}_2$ admits the decomposition
    \begin{align}
        v_g + \phi^{(2)} = \big(v_g + b_{12} \phi^{(2)}\big) + (1 - b_{12}) \phi^{(2)} \,,
    \end{align}
    with the first term belonging to $V_g$ and the second to $W$; thus
    \begin{align}
        \mathfrak{H}_2 = V_g \oplus W \,.
    \end{align}
    Equation \eqref{61} further shows that $W$ is $G=\mathrm{SO}_0(1,4)$-invariant. This contradicts the invariant-subspace structure summarized in Table \ref{Table 1}, according to which the action on $V^\prime\oplus\overline{V^\prime}$ necessarily extends into the gauge sector, so that $V_g$ admits no $G$-invariant complement in $\mathfrak{H}_2$. Hence, no such fixed map $b_{12}$ exists, and therefore $c_{12}\notin B^1(\pi_2,\pi_1)$. Proceeding analogously, one obtains
    \begin{enumerate}
        \item{$c_{12^\prime}\notin B^1(\pi^{}_{2^\prime},\pi^{}_1)$, and}

        \item{$c_{1{{\overline{2}^\prime}}}\notin B^1(\pi_{{\overline{2}^\prime}},\pi^{}_1)$.}
    \end{enumerate}}

    \item{$c^{}_{23}\notin B^1(\pi^{}_3,\pi^{}_2)$. Indeed, suppose, to the contrary, that $c^{}_{23}$ were a $1$-coboundary. Then there would exist a fixed linear map $b^{}_{23}\in C^0(\pi^{}_3,\pi^{}_2)$ such that $c^{}_{23} = (\delta b^{}_{23})$. Taking the adjoint and using $c^{}_{23} = c_{12}^{\ast}$ \eqref{akse0}, together with Eq. \eqref{maryam}, we obtain
    \begin{align}
        c_{12} = c_{23}^{\ast} = (\delta b^{}_{23})^{\ast} = -\delta(b_{23}^{\ast}) \,,
    \end{align}
    where $b_{23}^{\ast} \in C^0(\pi_2^\sharp,\pi_3^\sharp)$, $\pi^{}_2 \simeq \pi_2^\sharp$ \eqref{sharps}, and $\pi_3^\sharp \simeq \pi^{}_1$ \eqref{3sharp=1}. It then follows that $\delta(b_{23}^{\ast})\in B^1(\pi^{}_2,\pi^{}_1)$, and therefore $c_{12}\in B^1(\pi^{}_2,\pi^{}_1)$, contradicting the preceding item. Consequently, $c_{23}\notin B^1(\pi^{}_3,\pi^{}_2)$. Proceeding analogously, one obtains
    \begin{enumerate}
        \item{$c_{2^\prime 3}\notin B^1(\pi^{}_3,\pi^{}_{2^\prime})$, and}

        \item{$c_{{{\overline{2}^\prime}} 3}\notin B^1(\pi^{}_3, \pi_{{\overline{2}^\prime}})$.}
    \end{enumerate}}
\end{enumerate}
